import{_ as d,o as e,c as r,ag as i}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"单位相关 JSON 文件","description":"","frontmatter":{"title":"单位相关 JSON 文件"},"headers":[],"relativePath":"zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.md","filePath":"zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.md"}'),n={name:"zh/Modders/Mod-file-structure/4-Unit-related-JSON-files.md"};function o(s,t,a,l,h,u){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="单位相关-json-文件" tabindex="-1">单位相关 JSON 文件 <a class="header-anchor" href="#单位相关-json-文件" aria-label="Permalink to &quot;单位相关 JSON 文件&quot;">​</a></h1><h2 id="units-json" tabindex="-1">Units.json <a class="header-anchor" href="#units-json" aria-label="Permalink to &quot;Units.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Units.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件应包含你想要在模组中使用的所有单位列表，包括军事和民用单位。</p><p>每个单位具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>unitType</td><td>String</td><td>必需</td><td>单位的类型。必须在 <a href="#unittypes-json">UnitTypes.json</a> 中</td></tr><tr><td>cost</td><td>Integer</td><td>-1</td><td>建造此单位所需的生产力。所需的生产力始终为正数</td></tr><tr><td>movement</td><td>Integer</td><td>0</td><td>单位拥有的移动点数</td></tr><tr><td>strength</td><td>Integer</td><td>0</td><td>单位的近战攻击和防御力量。如果此值和 rangedStrength 被省略或为 0，则单位为民用</td></tr><tr><td>rangedStrength</td><td>Integer</td><td>0</td><td>单位的远程攻击和防御力量。如果省略，则单位不能进行远程攻击。如果使用，则必须设置 strength。</td></tr><tr><td>religiousStrength</td><td>Integer</td><td>0</td><td>单位的宗教攻击和防御力量</td></tr><tr><td>range</td><td>Integer</td><td>2</td><td>可以进行远程攻击的范围</td></tr><tr><td>interceptRange</td><td>Integer</td><td>0</td><td>在此范围内攻击的空中单位将被拦截</td></tr><tr><td>requiredTech</td><td>String</td><td>none</td><td>建造此单位所需的技术。必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#techs-json">Techs.json</a> 中</td></tr><tr><td>obsoleteTech</td><td>String</td><td>none</td><td>研究此技术后，将无法建造该单位。必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#techs-json">Techs.json</a> 中</td></tr><tr><td>requiredResource</td><td>String</td><td>none</td><td>建造此单位时消耗的资源。必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileresources-json">TileResources.json</a> 中</td></tr><tr><td>upgradesTo</td><td>String</td><td>none</td><td>当此单位可用时可以升级到的单位。必须在 <a href="#units-json">Units.json</a> 中</td></tr><tr><td>replaces</td><td>String</td><td>none</td><td>如果此单位是某个国家独有的，则这是它替换的单位。必须在 <a href="#units-json">Units.json</a> 中</td></tr><tr><td>uniqueTo</td><td>String</td><td>none</td><td>此单位独有的国家。必须在 <a href="/Unciv/zh/Modders/Mod-file-structure/2-Civilization-related-JSON-files.html#nations-json">Nations.json</a> 中</td></tr><tr><td>hurryCostModifier</td><td>Integer</td><td>0</td><td>如果此单位用金币购买，其价格增加此百分比</td></tr><tr><td>promotions</td><td>List of Strings</td><td>空</td><td>单位在建造时自动获得的所有晋升列表。每个晋升必须在 <a href="#unitpromotions-json">UnitPromotions.json</a> 中</td></tr><tr><td>uniques</td><td>List of Strings</td><td>空</td><td>此单位具有的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>replacementTextForUniques</td><td>String</td><td>none</td><td>如果提供，则显示此内容而不是 uniques 列表。可用于更好的格式化。</td></tr><tr><td>attackSound</td><td>String</td><td>none</td><td>单位攻击时播放的声音，如果还没有以单位名称命名的声音。对于可能的值，请参阅 <a href="/Unciv/zh/Modders/Images-and-Audio.html#声音">声音</a></td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><h2 id="unitpromotions-json" tabindex="-1">UnitPromotions.json <a class="header-anchor" href="#unitpromotions-json" aria-label="Permalink to &quot;UnitPromotions.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/UnitPromotions.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此文件列出了可用的单位晋升。</p><p>每个晋升必须有一个图标，除了以 &quot; I&quot;、&quot; II&quot;、&quot; III&quot; 结尾的进程（不允许 IV V VI）通过查找没有这些后缀的图标并添加星号来渲染。</p><p>请记住，晋升可以用 XP &quot;购买&quot;，但也可以由单位类型、建筑、奇观等授予。它们在单位升级时保留，因此国家独特单位可以在升级时继承的特殊属性应该在晋升中，而不是单位 json 中的 uniques/stats（例如：投石兵撤退）。</p><p>每个晋升具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td>请参阅上面的 &quot;I, II, III&quot; 进程</td></tr><tr><td>prerequisites</td><td>List of Strings</td><td>空</td><td>先决晋升</td></tr><tr><td>column</td><td>Integer</td><td>可选</td><td>确定在晋升选择器屏幕上的放置顺序。名称是历史性的，这些坐标不再直接控制放置。没有坐标的晋升确保最后放置。（...）</td></tr><tr><td>row</td><td>Integer</td><td>可选</td><td>…在没有坐标的基础模组中，没有先决条件的晋升按字母顺序排序并从上到下放置，屏幕的其余部分将逻辑地构建依赖关系。如果你的模组有&quot;Heal instantly&quot;，建议使用 row=0 将其放在顶部</td></tr><tr><td>unitTypes</td><td>List of Strings</td><td>空</td><td>此晋升适用的单位类型，如 <a href="#unittypes-json">UnitTypes.json</a> 中所指定</td></tr><tr><td>uniques</td><td>List of Strings</td><td>空</td><td>此晋升授予单位的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr><tr><td>innerColor</td><td>List</td><td>空</td><td><em>图标</em>的颜色</td></tr><tr><td>outerColor</td><td>List</td><td>空</td><td><em>背景</em>的颜色</td></tr></tbody></table><h2 id="unittypes-json" tabindex="-1">UnitTypes.json <a class="header-anchor" href="#unittypes-json" aria-label="Permalink to &quot;UnitTypes.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/UnitTypes.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>此可选文件用于定义新的单位类型。这些名称可以在 unitFilters 中使用，这些类型确定单位移动的域：在陆地上、在水上或通过空中。 对于基础规则集模组，如果省略文件或包含空列表，则<a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/UnitTypes.json" target="_blank" rel="noreferrer">来自 Vanilla 规则集的所有类型</a>会自动添加： Civilian、Melee、Ranged、Scout、Mounted、Armor、Siege、WaterCivilian、WaterMelee、WaterRanged、WaterSubmarine、WaterAircraftCarrier、Fighter、Bomber、AtomicBomber 和 Missile。</p><p>每个单位类型具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td></td></tr><tr><td>movementType</td><td>Enum</td><td>必需</td><td>单位移动的域。允许的值：&quot;Water&quot;、&quot;Land&quot;、&quot;Air&quot;</td></tr><tr><td>uniques</td><td>List of String</td><td>none</td><td>此晋升授予此类型单位的<a href="/Unciv/zh/Modders/uniques.html">独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table><h2 id="unitnamegroups-json" tabindex="-1">UnitNameGroups.json <a class="header-anchor" href="#unitnamegroups-json" aria-label="Permalink to &quot;UnitNameGroups.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/UnitNameGroups.json" target="_blank" rel="noreferrer">链接到原始文件</a></p><p>提供可以应用于单位的名称列表。一旦采用名称，就不会再次应用。</p><p>每个单位名称组具有以下结构：</p><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>必需</td><td>单位名称组的唯一名称（例如：Scientist）</td></tr><tr><td>names</td><td>List of String</td><td>必需</td><td>可以应用于组的名称列表（例如：Alan Turing）</td></tr><tr><td>uniques</td><td>List of String</td><td>none</td><td>在创建时应用于单位的<a href="/Unciv/zh/Modders/uniques.html#triggerable-uniques-触发型词条">可触发独特能力</a>列表</td></tr><tr><td>civilopediaText</td><td>List</td><td>空</td><td>请参阅 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#civilopedia-文本">civilopediaText 章节</a></td></tr></tbody></table>',23)])])}const m=d(n,[["render",o]]);export{p as __pageData,m as default};
